<?php
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit;}require dirname(__DIR__).'/app/Core/bootstrap.php';use App\Core\{Database,CronLock};use App\Services\GrowthService;if(!CronLock::acquire('growth')){echo"Growth já está em execução.\n";exit;}$pdo=Database::connection();$rows=$pdo->query("SELECT id,tenant_id,amount FROM payments WHERE status='paid' AND paid_at>=DATE_SUB(NOW(),INTERVAL 90 DAY) ORDER BY id DESC LIMIT 500")->fetchAll();$created=0;foreach($rows as $row){$before=(int)$pdo->query('SELECT COUNT(*) FROM acquisition_events')->fetchColumn();GrowthService::record('Purchase',['value'=>(float)$row['amount'],'currency'=>'BRL','payment_id'=>(int)$row['id']],(int)$row['tenant_id'],null,'payment-'.(int)$row['id'],true);$after=(int)$pdo->query('SELECT COUNT(*) FROM acquisition_events')->fetchColumn();if($after>$before)$created++;}echo"Compras reconciliadas: {$created}\n";
